import{_ as e,o as i,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- Ceph Performance","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- Ceph Performance","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph性能分析","CBT","COSBench","Tracepoint","Ceph性能基准"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_Ceph_Performance.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_Ceph_Performance.md","lastUpdated":1780459816000}'),t={name:"posts/2015/CDS_Infernalis_Day_2.2_--_Ceph_Performance.md"};function o(p,l,a,s,_,c){return i(),n("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph性能分析框架标准化</p><p><strong>参会人员</strong>：</p><ul><li>来自Intel的同事</li><li>Mark Nelson</li><li>会议主持人及参与者</li></ul><p><strong>会议内容</strong>：</p><p><strong>一、Ceph性能基准测试工具（CBT）与COSBench集成</strong></p><ol><li><p><strong>背景</strong>：</p><ul><li>CBT工具目前主要用于Ceph的性能基准测试，但不支持对象存储基准测试。</li><li>COSBench作为补充工具被提出，用于对象存储基准测试。</li></ul></li><li><p><strong>方案</strong>：</p><ul><li>将COSBench集成到CBT中，使其支持对象存储基准测试。</li><li>通过插件模型，将COSBench配置文件转换为CBT可识别的格式，并执行性能测试。</li><li>将COSBench测试结果集成到CBT结果中。</li></ul></li><li><p><strong>讨论</strong>：</p><ul><li>如何在CBT中实现COSBench的部署和配置。</li><li>如何确保COSBench和CBT之间的数据一致性。</li></ul></li></ol><p><strong>二、Ceph性能分析框架（Tracepoint）改进</strong></p><ol><li><p><strong>背景</strong>：</p><ul><li>现有的Ceph性能分析框架在追踪性能瓶颈方面存在困难。</li><li>部分Tracepoint缺乏语义，导致分析过程复杂且耗时。</li></ul></li><li><p><strong>方案</strong>：</p><ul><li>使用LTTng和Block和Blockzip作为工具进行性能分析。</li><li>引入语义化的Tracepoint，并使用统一的标识符跟踪单个I/O请求。</li><li>实现一个通用的Tracepoint框架，包括最重要的Tracepoint和可视化工具。</li></ul></li><li><p><strong>讨论</strong>：</p><ul><li>如何解决服务器系统时间差的问题。</li><li>如何在Zipkin中实现更清晰的性能分析结果。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>将COSBench集成到CBT中，并实现插件模型。</li><li>实现一个通用的Tracepoint框架，并引入语义化的Tracepoint。</li><li>将Andrew的Tracepoint补丁合并到Ceph代码库中。</li><li>优化Zipkin的Web界面，使其能够更清晰地展示性能分析结果。</li></ol><p><strong>四、其他</strong></p><ol><li>会议中讨论了COSBench对RGW性能的影响，以及如何检测性能退化。</li><li>讨论了在Tracepoint中添加不同级别的追踪功能。</li></ol><p><strong>五、总结</strong></p><p>本次会议讨论了Ceph性能分析框架的标准化方案，包括CBT与COSBench的集成和Tracepoint框架的改进。会议达成了初步的共识，并制定了后续行动计划。</p>',16)])])}const h=e(t,[["render",o]]);export{g as __pageData,h as default};
